from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
css_path=ROOT/"static"/"vano.css"
marker="/* VANO EXPERIENCE REFINEMENT · motion, handoff and microinteractions */"
css_path.write_text(css_path.read_text(encoding="utf-8").split(marker)[0].rstrip()+"\n\n"+"\n/* VANO EXPERIENCE REFINEMENT · motion, handoff and microinteractions */\n:root{\n  --vano-motion-fast:140ms;\n  --vano-motion-base:260ms;\n  --vano-motion-slow:460ms;\n  --vano-ease-out:cubic-bezier(.22,.72,.18,1);\n  --vano-ease-spring:cubic-bezier(.2,.86,.25,1.08);\n}\n\n.vano-x-pressing{\n  scale:.985;\n  filter:brightness(.96);\n  transition:scale 80ms ease,filter 80ms ease!important;\n}\n\n.vano-x-pop-in{animation:vano-micro-pop var(--vano-motion-base) var(--vano-ease-out) both}\n.vano-x-fade-in{animation:vano-micro-fade 280ms ease both}\n.is-motion-selected{animation:vano-selection-pulse 360ms var(--vano-ease-spring) both}\n.is-motion-soft{animation:vano-soft-highlight 300ms ease both}\n.is-motion-pop{animation:vano-micro-pop 320ms var(--vano-ease-out) both}\n\n@keyframes vano-micro-pop{\n  0%{opacity:.72;filter:brightness(.96) saturate(.92)}\n  55%{opacity:1;filter:brightness(1.025) saturate(1.03)}\n  100%{opacity:1;filter:none}\n}\n@keyframes vano-micro-fade{from{opacity:0}to{opacity:1}}\n@keyframes vano-selection-pulse{\n  0%{box-shadow:0 0 0 0 rgba(245,154,98,0)}\n  45%{box-shadow:0 0 0 4px rgba(245,154,98,.12)}\n  100%{box-shadow:0 0 0 0 rgba(245,154,98,0)}\n}\n@keyframes vano-soft-highlight{\n  0%,100%{filter:none}\n  45%{filter:brightness(1.035)}\n}\n\nhtml.vano-x-theme-changing body{\n  transition:filter 280ms ease,opacity 280ms ease!important;\n  filter:saturate(.94) brightness(.985);\n}\n\n/* Onboarding: step choreography and one continuous handoff to the map. */\nbody.vano-route-onboarding .ob500-form [data-ob-step]{\n  transform-origin:50% 12%;\n  transition:opacity 240ms var(--vano-ease-out),transform 340ms var(--vano-ease-out),filter 260ms ease;\n}\nbody.vano-route-onboarding .ob500-form [data-ob-step]:not(.is-active){\n  opacity:0;\n  transform:translate3d(18px,0,0) scale(.992);\n  filter:blur(2px);\n  pointer-events:none;\n}\nbody.vano-route-onboarding .ob500-form [data-ob-step].is-active{\n  opacity:1;\n  transform:none;\n  filter:none;\n}\nbody.vano-route-onboarding .ob500-form [data-ob-step].is-active.is-back{\n  animation:vano-ob-back 320ms var(--vano-ease-out) both;\n}\n@keyframes vano-ob-back{\n  from{opacity:.35;transform:translate3d(-16px,0,0) scale(.992)}\n  to{opacity:1;transform:none}\n}\nbody.vano-route-onboarding .ob500-map-card,\nbody.vano-route-onboarding .ob500-route-card,\nbody.vano-route-onboarding .ob500-language,\nbody.vano-route-onboarding .ob500-choice{\n  transition:border-color 180ms ease,background 220ms ease,box-shadow 220ms ease,scale 140ms ease,filter 180ms ease!important;\n}\nbody.vano-route-onboarding .ob500-map-card:has(input:checked),\nbody.vano-route-onboarding .ob500-route-card:has(input:checked),\nbody.vano-route-onboarding .ob500-language:has(input:checked),\nbody.vano-route-onboarding .ob500-choice:has(input:checked){\n  box-shadow:0 10px 28px rgba(44,35,29,.08),0 0 0 3px rgba(245,154,98,.08);\n}\nbody.vano-route-onboarding.is-launching .ob500-shell{\n  pointer-events:none;\n}\n.ob500-launch-screen{\n  position:fixed;inset:0;z-index:25000;\n  display:grid;place-items:center;padding:24px;\n  opacity:0;visibility:hidden;\n  transition:opacity 260ms ease,visibility 260ms step-end;\n}\n.ob500-launch-screen.is-visible{opacity:1;visibility:visible;transition:opacity 260ms ease}\n.ob500-launch-backdrop{\n  position:absolute;inset:0;\n  background:rgba(13,12,11,.72);\n  backdrop-filter:blur(18px) saturate(125%);\n  -webkit-backdrop-filter:blur(18px) saturate(125%);\n}\n.ob500-launch-core{\n  position:relative;z-index:1;\n  width:min(390px,calc(100vw - 36px));\n  padding:34px 30px 26px;\n  border:1px solid rgba(255,255,255,.14);\n  border-radius:30px;\n  background:linear-gradient(165deg,rgba(31,28,26,.98),rgba(16,15,14,.98));\n  box-shadow:0 32px 90px rgba(0,0,0,.34);\n  text-align:center;\n  transform:translateY(14px) scale(.97);\n  transition:transform 460ms var(--vano-ease-spring);\n}\n.ob500-launch-screen.is-visible .ob500-launch-core{transform:none}\n.ob500-launch-mark{\n  position:relative;width:96px;height:96px;margin:0 auto 22px;display:grid;place-items:center;\n}\n.ob500-launch-mark>span{\n  position:relative;z-index:2;width:62px;height:62px;border-radius:22px;\n  display:grid;place-items:center;color:#fff;\n  background:linear-gradient(145deg,#ffc39b,#f59a62 55%,#d9703f);\n  box-shadow:0 16px 38px rgba(217,112,63,.27),inset 0 1px 0 rgba(255,255,255,.44);\n}\n.ob500-launch-mark .ring{\n  position:absolute;inset:8px;border:1px solid rgba(245,154,98,.24);border-radius:50%;\n  animation:vano-launch-ring 1.45s ease-out infinite;\n}\n.ob500-launch-mark .r2{animation-delay:.38s}\n@keyframes vano-launch-ring{0%{scale:.68;opacity:.75}80%,100%{scale:1.34;opacity:0}}\n.ob500-launch-copy b{display:block;color:#fff;font-size:22px;letter-spacing:-.6px}\n.ob500-launch-copy small{display:block;margin-top:7px;color:#a9a29d;font-size:12px}\n.ob500-launch-track{\n  height:4px;margin-top:26px;border-radius:99px;overflow:hidden;background:rgba(255,255,255,.08)\n}\n.ob500-launch-track i{\n  display:block;width:38%;height:100%;border-radius:inherit;\n  background:linear-gradient(90deg,transparent,#ffc39b,#f59a62,transparent);\n  animation:vano-launch-track 860ms ease-in-out infinite;\n}\n@keyframes vano-launch-track{from{transform:translateX(-120%)}to{transform:translateX(350%)}}\n\n/* Map entry handoff: short, deliberate, and never a second full splash. */\n.vano-entry-splash{\n  position:fixed;inset:0;z-index:24000;\n  display:grid;place-items:center;\n  background:rgba(249,248,246,.96);\n  opacity:0;visibility:hidden;\n  transition:opacity 340ms ease,visibility 340ms step-end;\n}\nhtml[data-vano-theme=\"black\"] .vano-entry-splash{background:rgba(11,11,12,.96)}\n.vano-entry-splash.show{opacity:1;visibility:visible;transition:opacity 220ms ease}\n.vano-entry-splash.hide{opacity:0;pointer-events:none}\n.vano-entry-splash-inner{\n  width:min(330px,calc(100vw - 44px));\n  display:grid;justify-items:center;text-align:center;\n  transform:translateY(10px) scale(.98);\n  transition:transform 460ms var(--vano-ease-spring),opacity 300ms ease;\n}\n.vano-entry-splash.show .vano-entry-splash-inner{transform:none}\n.vano-entry-splash-mark{position:relative;width:86px;height:86px;display:grid;place-items:center}\n.vano-entry-splash-mark img{\n  width:62px;height:62px;border-radius:20px;position:relative;z-index:2;\n  box-shadow:0 14px 35px rgba(59,45,35,.16);\n}\n.vano-entry-splash-mark i{\n  position:absolute;inset:6px;border-radius:50%;border:1px solid rgba(245,154,98,.28);\n  animation:vano-entry-ring 1.2s ease-out infinite;\n}\n@keyframes vano-entry-ring{from{scale:.72;opacity:.8}to{scale:1.42;opacity:0}}\n.vano-entry-splash-copy strong{display:block;margin-top:12px;font-size:21px;letter-spacing:-.65px;color:#27231f}\n.vano-entry-splash-copy span{display:block;margin-top:5px;font-size:11px;color:#7c746d}\nhtml[data-vano-theme=\"black\"] .vano-entry-splash-copy strong{color:#fff8f2}\nhtml[data-vano-theme=\"black\"] .vano-entry-splash-copy span{color:#9e958e}\n.vano-entry-splash-track{\n  width:150px;height:3px;margin-top:22px;border-radius:99px;overflow:hidden;background:rgba(80,65,55,.10)\n}\n.vano-entry-splash-track i{\n  display:block;width:44%;height:100%;border-radius:inherit;background:#f59a62;\n  animation:vano-entry-progress 700ms var(--vano-ease-out) both;\n}\n@keyframes vano-entry-progress{from{transform:translateX(-105%)}to{transform:translateX(228%)}}\n.vano-entry-splash.is-handoff .vano-entry-splash-mark img{animation:vano-handoff-mark 520ms var(--vano-ease-spring) both}\n@keyframes vano-handoff-mark{0%{scale:.86;rotate:-4deg}65%{scale:1.04;rotate:1deg}100%{scale:1;rotate:0}}\n\n/* Profile: selection and save feedback without moving the layout. */\nbody.vano-route-profile .profile350-map-card,\nbody.vano-route-profile [data-language-card],\nbody.vano-route-profile .profile350-chip-select label,\nbody.vano-route-profile .profile350-accent label{\n  transition:border-color 180ms ease,background 220ms ease,box-shadow 220ms ease,filter 180ms ease!important;\n}\nbody.vano-route-profile .profile350-map-card.is-selected,\nbody.vano-route-profile [data-language-card].is-selected{\n  box-shadow:0 10px 28px rgba(57,46,37,.07),0 0 0 3px rgba(245,154,98,.08);\n}\nbody.vano-route-profile .profile350-reveal{\n  opacity:0;transform:translateY(12px);\n  transition:opacity 420ms var(--vano-ease-out),transform 480ms var(--vano-ease-out);\n}\nbody.vano-route-profile .profile350-reveal.is-visible{opacity:1;transform:none}\nbody.vano-route-profile.is-saving-profile .profile350-savebar{filter:saturate(.92)}\nbody.vano-route-profile [data-save-state=\"saving\"] .profile350-savebar{cursor:progress}\n\n/* Route and overlay choreography. */\n.vano-x-route-enter .vr-hero{animation:vano-route-rise 420ms var(--vano-ease-out) both}\n.vano-x-route-enter .vano-primary-transport-row{animation:vano-route-rise 460ms 45ms var(--vano-ease-out) both}\n.vano-x-route-enter .route-variants{animation:vano-route-rise 500ms 80ms var(--vano-ease-out) both}\n.vano-x-route-enter .start-trip-cta{animation:vano-route-rise 520ms 115ms var(--vano-ease-out) both}\n@keyframes vano-route-rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}\n\nbody.nav-launching .nav-maneuver-top,\nbody.nav-launching .nav-street-chip,\nbody.nav-launching .nav-control-stack{\n  opacity:.45;\n  transition:opacity 480ms ease;\n}\nbody:not(.nav-launching) .nav-maneuver-top,\nbody:not(.nav-launching) .nav-street-chip,\nbody:not(.nav-launching) .nav-control-stack{\n  transition:opacity 380ms ease;\n}\n\n/* Camera free/follow state feedback stays visual, not jumpy. */\nbody.nav-map-free #navFollowToggle{\n  box-shadow:0 0 0 4px rgba(245,154,98,.12);\n}\nbody[data-nav-camera-state=\"RECENTERING\"] #navFollowToggle,\nbody[data-nav-camera-state=\"RECENTERING\"] #navRecenter,\nbody[data-nav-camera-state=\"RECENTERING\"] #recenterBtn{\n  animation:vano-recenter-pulse 820ms ease-in-out infinite;\n}\n@keyframes vano-recenter-pulse{0%,100%{filter:none}50%{filter:brightness(1.12);box-shadow:0 0 0 5px rgba(245,154,98,.09)}}\n\n@media (hover:hover) and (pointer:fine){\n  .planner-preset,.nearby-service,.sub-action,.profile350-map-card,.ob500-map-card,.ob500-route-card{\n    transition:transform 180ms var(--vano-ease-out),box-shadow 200ms ease,filter 180ms ease!important;\n  }\n  .planner-preset:hover,.nearby-service:hover,.sub-action:hover{transform:translateY(-1px)}\n}\n\n@media (prefers-reduced-motion:reduce){\n  *,*::before,*::after{\n    scroll-behavior:auto!important;\n    animation-duration:.001ms!important;\n    animation-iteration-count:1!important;\n    transition-duration:.001ms!important;\n  }\n  .ob500-launch-screen,.vano-entry-splash{backdrop-filter:none!important;-webkit-backdrop-filter:none!important}\n  body.vano-route-profile .profile350-reveal{opacity:1!important;transform:none!important}\n}\n".strip()+"\n",encoding="utf-8")

test_path=ROOT/"tests"/"test_frontend_performance.py"
text=test_path.read_text(encoding="utf-8")
if "test_motion_refinement_contract" not in text:
    text += """


def test_motion_refinement_contract():
    css = (ROOT / "static" / "vano.css").read_text(encoding="utf-8")
    onboarding = (ROOT / "static" / "vano-onboarding.js").read_text(encoding="utf-8")
    map_js = (ROOT / "static" / "vano-map.js").read_text(encoding="utf-8")
    assert "VANO EXPERIENCE REFINEMENT" in css
    assert "vano.motion.handoff.v1" in onboarding
    assert "vano.motion.handoff.v1" in map_js
    assert "settleMeters" in map_js
    assert "fitEndpoints()" in map_js
"""
    test_path.write_text(text,encoding="utf-8")

(ROOT/".github"/"workflows"/"experience-css.yml").unlink(missing_ok=True)
Path(__file__).unlink(missing_ok=True)
